def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    d_run = 0
    for h in reversed(history):
        if h[1] == 'D':
            d_run += 1
        else:
            break
    if d_run >= 5:
        return 'D'

    if n >= 97:
        return 'C'

    last = history[-1]
    pair = last[0] + last[1]

    if pair == 'CD':
        if n >= 2 and history[-2][0] == 'D' and history[-2][1] == 'C':
            return 'C'
        return 'D'

    if pair == 'DD':
        return 'C'

    if pair == 'DC':
        return 'C'

    if n >= 93:
        return 'C'

    c_run = 0
    for h in reversed(history):
        if h[1] == 'C':
            c_run += 1
        else:
            break

    opp_d = 0
    for h in history:
        if h[1] == 'D':
            opp_d += 1

    last_resp = ''
    for i in range(n - 1, 0, -1):
        if history[i - 1][0] == 'D':
            last_resp = history[i][1]
            break

    if last_resp == 'C':
        if opp_d <= 5 and (n - opp_d) >= 10:
            if rng.random() < 0.45:
                return 'D'
        elif c_run >= 5:
            if rng.random() < 0.20:
                return 'D'
        elif c_run >= 2:
            if rng.random() < 0.08:
                return 'D'
    elif last_resp == 'D':
        if c_run >= 30 and rng.random() < 0.02:
            return 'D'
    else:
        if c_run >= 20 and rng.random() < 0.03:
            return 'D'

    return 'C'
